Action: run_sql({'query': "WITH thai_ids AS (\n    SELECT DISTINCT ec.gmap_id\n    FROM establishment_categories ec\n    JOIN category c ON ec.category_id = c.category_id\n    WHERE c.category LIKE '%Thai%'\n),\nkorean_ids AS (\n    SELECT DISTINCT ec.gmap_id\n    FROM establishment_categories ec\n    JOIN category c ON ec.category_id = c.category_id\n    WHERE c.category LIKE '%Korean%'\n),\nthai_metrics AS (\n    SELECT \n        'Thai' as cuisine,\n        AVG(e.avg_rating) as avg_rating,\n        COALESCE(SUM(v.violation_occurrences), 0) as total_violations\n    FROM thai_ids t\n    JOIN establishments e ON t.gmap_id = e.gmap_id\n    LEFT JOIN inspections i ON e.slchd_establishment_key = i.slchd_establishment_key\n    LEFT JOIN violations v ON i.inspection_id = v.inspection_id\n),\nkorean_metrics AS (\n    SELECT \n        'Korean' as cuisine,\n        AVG(e.avg_rating) as avg_rating,\n        COALESCE(SUM(v.violation_occurrences), 0) as total_violations\n    FROM korean_ids k\n    JOIN establishments e ON k.gmap_id = e.gmap_id\n    LEFT JOIN inspections i ON e.slchd_establishment_key = i.slchd_establishment_key\n    LEFT JOIN violations v ON i.inspection_id = v.inspection_id\n)\nSELECT * FROM thai_metrics\nUNION ALL\nSELECT * FROM korean_metrics;"})

